import { z } from 'zod';
const EnvSchema = z.object({
  API_URL: z.string().url(),
  RETRIES: z.coerce.number().min(0).max(5),
  DEBUG: z.coerce.boolean()
});
export const env = EnvSchema.parse(process.env);

test('Debug Mode', async ({ page }) => {
  if (process.env.PWDEBUG) {
    await page.pause();
  }
});

