import type { Reporter, TestCase, TestResult } from '@playwright/test/reporter';
class MyCustomReporter implements Reporter {
  onTestEnd(test: TestCase, result: TestResult) {
    if (result.status === 'failed') {
      sendSlackMessage(`Test ${test.title} failed!`);
    }
  }
}

Hard.code:
class FlakyReporter implements Reporter {
  onTestEnd(test: TestCase, result: TestResult) {
    if (test.outcome() === 'flaky') {
      quarantineAPI.markAsFlaky(test.title);
    }
  }
}

export default class PerfReporter implements Reporter {
  onStepEnd(test: TestCase, result: TestResult, step: TestStep) {
    if (step.category === 'pw:api' && step.duration > 5000) {
      logWarning(`Slow API call: ${step.title} (${step.duration}ms)`);
    }
  }
}
